/** Byte length of the rendered CV, inlined by vite.config.ts / vitest.config.ts. */
declare const __CV_BYTES__: number;
/** SITE_URL with no trailing slash, inlined the same way; "" in dev without one. */
declare const __SITE_URL__: string;
/** ISO timestamp of the build (or dev-server start); the default for `commands.system.since`. */
declare const __BUILD_TIME__: string;
